// Extract email content and metadata
const item = $input.item.json;

// Get email content (prefer plain text, fallback to HTML)
const emailContent = item.text || item.textAsHtml || item.html || '';

// Get subject
const emailSubject = item.subject || 'No Subject';

// Get sender email
let emailSource = '';
if (item.from) {
  if (typeof item.from === 'string') {
    emailSource = item.from;
  } else if (item.from.address) {
    emailSource = item.from.address;
  } else if (item.from.value && item.from.value[0]) {
    emailSource = item.from.value[0].address;
  }
}

// Prepare payload for Commission API
return {
  json: {
    email_content: emailContent,
    email_subject: emailSubject,
    email_source: emailSource,
    // Keep original email data for reference
    _original: {
      date: item.date,
      messageId: item.messageId
    }
  }
};

// Format success message
const data = $json.data;
const validation = $json.validation;

const message = `✅ Commission Processed Successfully!

📋 Transaction Details:
• Transaction ID: ${data.transaction_id}
• Property: ${data.property_address}
• Sale Amount: $${data.sale_amount.toLocaleString()}
• Commission Rate: ${(data.commission_rate * 100).toFixed(1)}%
• Total Commission: $${data.total_commission.toLocaleString()}
• Closing Date: ${data.closing_date}
• Status: ${data.status}

👥 Commission Splits:
${data.splits.map(s => `• ${s.agent_name}: ${(s.percentage * 100).toFixed(0)}% = $${s.amount.toLocaleString()}`).join('\n')}

📊 AI Confidence: ${(validation.confidence_score * 100).toFixed(1)}%

✨ Ready for verification!`;

return {
  json: {
    message: message,
    transaction_id: data.transaction_id,
    total_commission: data.total_commission,
    confidence_score: validation.confidence_score
  }
};

// Format low confidence alert
const data = $json.data;
const validation = $json.validation;

const message = `⚠️ Low Confidence Commission - Manual Review Needed

📋 Transaction Details:
• Transaction ID: ${data.transaction_id}
• Property: ${data.property_address}
• Total Commission: $${data.total_commission.toLocaleString()}

⚠️ Issues:
• AI Confidence: ${(validation.confidence_score * 100).toFixed(1)}% (below 70% threshold)
${validation.warnings.length > 0 ? '• Warnings: ' + validation.warnings.join(', ') : ''}
${validation.errors.length > 0 ? '• Errors: ' + validation.errors.join(', ') : ''}

👉 Action Required:
Please review this commission manually in the system.

View: http://localhost:5000/api/v1/commissions/${data.id}`;

return {
  json: {
    message: message,
    transaction_id: data.transaction_id,
    confidence_score: validation.confidence_score,
    requires_review: true
  }
};

// Format error message
const error = $json.error || 'Unknown error';
const message = $json.message || 'No details available';

const errorMsg = `❌ Commission Parsing Failed

🔴 Error: ${error}
📝 Details: ${message}

📧 Original Email:
• Subject: ${$node["Extract Email Data"].json.email_subject}
• From: ${$node["Extract Email Data"].json.email_source}

👉 Action Required:
Please check the email format and try again, or process manually.

API Logs: Check logs/app.log for details`;

return {
  json: {
    message: errorMsg,
    error: error,
    failed: true
  }
};
